import json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
research=json.loads((root/'data/competitor_data.json').read_text())
sources=[
('B01','Apple Developer annual membership','https://developer.apple.com/programs/enroll/','US$99 per year; tax and local pricing may vary.'),
('B02','Supabase Pro published starting price','https://supabase.com/pricing','From $25/month; first project included. Usage, add-ons and extra projects can add costs.'),
('B03','Cloudflare Workers published pricing','https://developers.cloudflare.com/workers/platform/pricing/','Paid account minimum $5/month plus usage beyond allowances.'),
('B04','Apple distribution commissions','https://developer.apple.com/programs/whats-included/','30% general published rate; 15% for eligible programs and qualifying subscriptions. Eligibility not established.'),
('B05','Google Play registration','https://support.google.com/googleplay/android-developer/answer/6112435','US$25 one-time registration; not an annual fee.'),
('B06','Stripe domestic card pricing','https://stripe.com/pricing','2.9% plus $0.30 for successful domestic-card transactions. Other charges and subscription tools may apply.'),
('B07','Apple Small Business Program','https://developer.apple.com/app-store/small-business-program/','15% requires qualification and enrollment; not assumed in the default model.')]
sourceMap={s[0]:s for s in sources}
costs=[]
def cost(id,name,category,amount,kind='fixed',frequency='monthly',status='Estimated',assumptions='',source=None,enabled=True,maximum=None,amort=0):
 s=sourceMap.get(source)
 costs.append(dict(id=id,name=name,category=category,description=name+' supports the proposed digital fitness subscription.',kind=kind,frequency=frequency,amount=amount,currency='USD',unit='percent of revenue' if kind=='percent' else 'per billing transaction' if kind=='transaction' else 'per active customer per period' if kind=='unit' else 'business total',target='all',status=status,assumptions=assumptions,source=s[2] if s else '',sourceId=source or '',checked='2026-10-27' if s else '',reference=amount,referenceStatus=status,referenceNote=s[3] if s else 'Planning reference only; no verified industry benchmark. Obtain quotes or usage measurements.',enabled=enabled,max=maximum or max(100,amount*4),amortMonths=amort,custom=False))
cost('maintenance','App maintenance and bug fixes','Engineering',1200,assumptions='Assume 20 contractor hours × $60. Neither hours nor rate is a sourced quote; includes routine QA, not initial build.',maximum=12000)
cost('founder','Founder operating compensation','People',1500,assumptions='Opportunity-cost allowance for founder operations; edit to the compensation actually required. Not an employee wage benchmark.',maximum=15000)
cost('payroll','Employer taxes and benefits reserve','People',0,status='Illustrative',assumptions='Disabled placeholder: employment status, state, benefits and tax rates are unknown. Contractor budgets exclude employee benefits.',enabled=False,maximum=5000)
cost('hosting','Application hosting baseline','Technology',5,status='Researched',source='B03',assumptions='Hypothetical Cloudflare Workers Paid deployment for the venture, not hosting for this free static laboratory. Usage billed separately.',maximum=500)
cost('database','Database and authentication baseline','Technology',25,status='Researched',source='B02',assumptions='Hypothetical one-project Supabase Pro. Baseline only; performance and quotas require testing.',maximum=1000)
cost('overage','Infrastructure usage reserve','Technology',.15,kind='unit',status='Illustrative',assumptions='Per active customer-month placeholder for storage, bandwidth and usage above baseline allowances. No measured workload.',maximum=10)
cost('ai','AI generation and safety checks','Technology',.75,kind='unit',status='Illustrative',assumptions='Per active customer-month placeholder; model, token count, caching, retries and moderation workload are unknown. Measure before launch.',maximum=20)
cost('monitoring','Monitoring security and backups','Technology',40,assumptions='Combined tool budget excludes managed database backups already included. Select actual tools and check usage tiers.',maximum=1000)
cost('nutrition','Nutrition and exercise content review','Product & safety',300,assumptions='6 hours × $50 for qualified review; neither rate nor scope is quoted. Professional review and appropriate limits are needed for the app concept.',maximum=6000)
cost('data-license','Food data licensing and attribution','Product & safety',0,status='Illustrative',assumptions='Open datasets may have no access fee but licensing, attribution, quality and rate limits still need review. Zero is not proof of no compliance work.',maximum=2000)
cost('support','Customer support time','Support',1,kind='unit',assumptions='3 minutes per active customer-month × $20/hour. Workload and rate are estimates; includes no free-user support.',maximum=15)
cost('marketing','Advertising and creative budget','Marketing',300,assumptions='Monthly spending choice; no assumed customer acquisition rate or guaranteed customers. No CAC projection.',maximum=12000)
cost('accounting','Bookkeeping and administration','Compliance',100,assumptions='Small online-business budget; location, entity and service quotes unknown.',maximum=2000)
cost('insurance','Liability and cyber insurance allowance','Compliance',100,assumptions='Illustrative planning allowance requiring a broker quote; coverage and legal requirements are not established.',status='Illustrative',maximum=2500)
cost('legal','Ongoing privacy and legal review','Compliance',100,assumptions='Planning reserve for privacy, terms and app safety issues; not legal advice or a fee quote.',maximum=3000)
cost('domain','Domain renewal','Technology',20,frequency='annual',assumptions='Domain extension and registrar unknown; no supplier quote. Monthly equivalent = annual amount / 12.',maximum=200)
cost('apple','Apple Developer membership','Distribution',99,frequency='annual',status='Researched',source='B01',assumptions='Scenario assumes iOS distribution. Published annual fee only; taxes excluded.',maximum=500)
cost('store-fee','App store commission','Distribution',30,kind='percent',status='Researched',source='B04',assumptions='Conservative scenario applies Apple general 30% rate to all allocated revenue. 15% program/qualifying subscription eligibility is not confirmed. Disable for web-only plans or allocate to the appropriate plan.',maximum=50)
cost('web-fee','Web card percentage fee','Distribution',2.9,kind='percent',status='Researched',source='B06',assumptions='Optional alternative to store fees; default disabled. Assumes US domestic cards. Disable store commission or allocate fees to separate plans.',enabled=False,maximum=10)
cost('web-txn','Web card transaction fee','Distribution',.30,kind='transaction',status='Researched',source='B06',assumptions='Optional web alternative, disabled by default. $0.30 per monthly charge or $0.30/12 per active annual customer-month. Billing software, refunds and disputes may add costs.',enabled=False,maximum=5)
cost('build','Initial app design and development','Startup',12000,frequency='once',assumptions='200 hours × $60 planning estimate. Actual scope and quote unknown. Default startup cash only; enter amortization months only if you deliberately choose accounting amortization.',maximum=100000)
cost('setup-legal','Entity privacy terms and launch review','Startup',1500,frequency='once',assumptions='Launch legal and entity setup allowance; jurisdiction and quotes unknown. Kept outside recurring break-even.',maximum=20000)
cost('devices','Development and test equipment','Startup',1800,frequency='once',assumptions='Laptop and test device allowance. 36-month straight-line depreciation, zero salvage, chosen teaching assumption. Cash shown in startup; depreciation included once in fixed operating costs.',maximum=10000,amort=36)
cost('google','Google Play registration','Startup',25,frequency='once',status='Researched',source='B05',assumptions='Optional Android launch scenario. Disabled until chosen; fee paid once, not annual.',enabled=False,maximum=200)
venture={**research['venture'],'name':'Threshold Fit','name_source':'Name observed in original venture website src/App.tsx on 2026-10-27; Mission 1 itself was unnamed.','confirmed':'AI fitness companion concept for busy adults; proposed workouts, meals, warm-ups, stretches and reminders.','assumptions':'US/USD launch slice, paid subscription, a remote founder, contractor support and all-store revenue are scenarios. No physical inventory, office lease or full-time hires are assumed.'}
model=dict(venture=venture,websites={'setup_original_repository_url':'https://acant2006-cmd.github.io/Creative-Website-/','original_live_url':'https://acant2006-cmd.github.io/Creative-Website-/','resolved_repository_url':'https://github.com/acant2006-cmd/Creative-Website-','laboratory_repository':'https://github.com/acant2006-cmd/Competitive-Research-Pricing','note':'Setup supplied a Pages live URL in the repository field. Preserved verbatim; the matching repository was inspected read-only.'},products=[dict(id='plan-main',name='Threshold Fit Membership',description='One integrated fitness and meal-planning app concept.',billing='monthly',price=14.99,quantity=500,unitCost=0,features=research['venture']['features'],addons='None proposed',scenario=False)],costs=costs,downside=.5,upside=1.5,volumeScenarios=[],allocation='active-customer share')
(root/'data/defaults.json').write_text(json.dumps({'model':model,'sources':[dict(id=s[0],title=s[1],url=s[2],note=s[3],checked='2026-10-27') for s in sources]},indent=2))
print(len(costs),'costs generated')
